/**
 * The web app runs the compiled engine (software/app/engine, built with `npm run build:engine`).
 * This test fails if app/engine is stale: it must give exactly the same result as src/domain
 * for every scenario, day and environment of the real dataset.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { evaluateDay as fromTs } from '../src/domain/index.ts';
// @ts-ignore — plain JS module generated by tsc
import { evaluateDay as fromApp } from '../app/engine/index.js';

const root = new URL('../../', import.meta.url);
const cfg = JSON.parse(readFileSync(new URL('contracts/medical-ranges-config.json', root), 'utf8'));
const ds = JSON.parse(readFileSync(new URL('data/synthetic/galley-14day-scenarios.json', root), 'utf8'));

test('app/engine matches src/domain on all 5 scenarios x 14 days x 3 environments', () => {
  for (const [name, sc] of Object.entries<any>(ds.scenarios)) {
    for (let i = 0; i < sc.days.length; i++) {
      for (const environment of ['ISS', 'MOON', 'MARS'] as const) {
        const input = { days: sc.days, index: i, usual: ds.baseline_profile, cfg, environment, crewId: 'CREW-A' };
        assert.deepEqual(fromApp(input), fromTs(input), `${name} day ${i + 1} ${environment}`);
      }
    }
  }
});
